import{time,stamp,parse,serialize,reflow,issues}from'./core.js';
const $=id=>document.getElementById(id);let rows=[],history=[],selected=0,fileName='captions',videoURL='';const sample='1\n00:00:00,000 --> 00:00:02,800\nहर कहानी की शुरुआत एक छोटे कदम से होती है।\n\n2\n00:00:02,800 --> 00:00:05,400\nBas shuru karo. Baaki raasta mil jayega.\n\n3\n00:00:05,200 --> 00:00:05,800\nYour next story starts here.\n';
function tell(s){$('message').textContent=s}function save(){history.push(structuredClone(rows));if(history.length>30)history.shift();$('undo').disabled=false}function max(){return Number($('width').value)||32}function preview(){if(!rows.length)return;$('previewText').textContent=rows[selected]?.text||'';if(!videoURL)$('currentTime').textContent=stamp(rows[selected]?.start||0)}
function audit(){let total=0;rows.forEach((r,i)=>{const a=issues(rows,i,max());total+=a.length?1:0;const el=$('issues-'+i);if(el){el.textContent=a.join(' ');el.className=a.length?'warning':''}});$('summary').textContent=total?`${total} caption${total===1?'':'s'} to check · edits are applied immediately`:'All captions pass the current checks.';$('summary').className=total?'warning':'good';$('download').disabled=!rows.length||rows.some(r=>!Number.isFinite(r.start)||!Number.isFinite(r.end)||r.start<0||r.end<=r.start||!r.text.trim());preview()}
function render(){const list=$('list');list.replaceChildren();$('count').textContent=`${rows.length} captions`;for(const id of ['wrap','applyShift'])$(id).disabled=!rows.length;$('undo').disabled=!history.length;rows.forEach((r,i)=>{const article=document.createElement('article');article.className='caption';const top=document.createElement('div');top.className='caption-top';const n=document.createElement('span');n.className='number';n.textContent=String(i+1).padStart(2,'0');top.append(n);for(const field of ['start','end']){const inp=document.createElement('input');inp.className='time-input';inp.value=stamp(r[field]);inp.setAttribute('aria-label',`Caption ${i+1} ${field} time`);inp.addEventListener('change',()=>{const value=time(inp.value);if(!Number.isFinite(value)){inp.value=stamp(r[field]);tell('Use HH:MM:SS,mmm for timestamps.');return}save();r[field]=value;audit()});top.append(inp)}const play=document.createElement('button');play.className='play';play.textContent='View';play.setAttribute('aria-label',`Preview caption ${i+1}`);play.onclick=()=>{selected=i;if(videoURL){$('video').currentTime=r.start/1000;updateVideo()}preview()};top.append(play);const area=document.createElement('textarea');area.value=r.text;area.setAttribute('aria-label',`Caption ${i+1} text`);area.addEventListener('focus',()=>{save();selected=i;preview()});area.addEventListener('input',()=>{r.text=area.value;audit()});const warning=document.createElement('div');warning.id='issues-'+i;article.append(top,area,warning);list.append(article)});audit()}
function load(text,name){const parsed=parse(text);if(rows.length)save();rows=parsed;selected=0;fileName=name.replace(/\.srt$/i,'');$('filename').textContent=name;render();tell('Subtitles loaded. Review the highlighted captions before exporting.')}
$('sample').onclick=()=>load(sample,'sample.srt');$('srt').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Please choose an SRT file smaller than 2 MB.');load(await f.text(),f.name)}catch(err){tell(err.message)}e.target.value=''};
function shiftAll(seconds){if(!Number.isFinite(seconds)||Math.abs(seconds)>86400)throw Error('Enter a shift between −86400 and 86400 seconds.');if(!rows.length)throw Error('Open subtitles first.');const delta=Math.round(seconds*1000);if(rows.some(r=>r.start+delta<0||r.end+delta<0))throw Error('This shift would move a caption before 00:00. Use a smaller negative shift.');save();rows=rows.map(r=>({...r,start:r.start+delta,end:r.end+delta}));render();tell(`All captions shifted by ${seconds} seconds.`);return{captions:rows.length,seconds}}
$('applyShift').onclick=()=>{try{if(!$('shift').value.trim())throw Error('Enter a shift in seconds.');shiftAll(Number($('shift').value))}catch(e){tell(e.message)}};
$('wrap').onclick=()=>{const limit=Number($('width').value);if(!Number.isInteger(limit)||limit<10||limit>80){tell('Choose a whole number from 10 to 80.');return}save();rows=rows.map(r=>({...r,text:reflow(r.text,limit)}));render();tell('Line breaks updated. Longer captions are flagged for manual editing.')};$('width').onchange=()=>{if(rows.length)audit()};$('undo').onclick=()=>{if(history.length){rows=history.pop();selected=0;render();tell('Last change undone.')}};
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([serialize(rows)],{type:'application/x-subrip;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=fileName+'-fixed.srt';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);tell('Your corrected SRT is ready. Check your browser downloads.')};
$('videoFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(f);$('video').src=videoURL;$('video').parentElement.classList.add('has-video');$('overlay').hidden=false;$('previewHelp').textContent='Play the video to check subtitle timing. Captions are previewed here, not burned into the video.'};
function updateVideo(){const ms=$('video').currentTime*1000;$('currentTime').textContent=stamp(ms);$('overlay').textContent=rows.filter(r=>ms>=r.start&&ms<r.end).map(r=>r.text).join('\n')}$('video').ontimeupdate=updateVideo;$('video').onseeked=updateVideo;$('video').onerror=()=>tell('This video format could not be played by your browser. Try an MP4 with H.264 video.');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'shift_subtitle_timing',title:'Shift subtitle timing',description:'Shift all loaded subtitle timestamps by a number of seconds. Negative values move captions earlier.',inputSchema:{type:'object',properties:{seconds:{type:'number',minimum:-86400,maximum:86400}},required:['seconds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.seconds!=='number')throw Error('seconds must be a number');return shiftAll(input.seconds)}})).catch(()=>{})}catch{}}
